const filterButtons=document.querySelectorAll('[data-filter]');filterButtons.forEach(button=>button.addEventListener('click',()=>{filterButtons.forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.card').forEach(card=>card.hidden=button.dataset.filter!=='all'&&!card.dataset.type.split(' ').includes(button.dataset.filter))}));const forces={lift:'Lift is the aerodynamic force perpendicular to the airflow. Wings redirect air and create pressure differences that help support the airplane’s weight.',weight:'Weight is the downward force of gravity acting on the airplane, its passengers, and everything on board. In steady level flight, lift balances weight.',thrust:'Thrust moves an airplane forward. A propeller accelerates air backward, while a jet engine produces a fast-moving exhaust stream.',drag:'Drag is aerodynamic resistance to motion through the air. Streamlined shapes reduce drag; in steady flight at constant speed, thrust balances it.'};document.querySelectorAll('.force-tabs button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.force-tabs button').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.force-label').forEach(l=>l.classList.toggle('on',l.dataset.force===button.dataset.force));document.querySelector('#force-text').textContent=forces[button.dataset.force]}));